<script>
  import { traverseAndScramble } from '@splendidlabz/utils/dom'
  import { onMount } from 'svelte'

  let { class: klass = '', ref = $bindable(null), excludes = [], children, ...rest } = $props()

  onMount(_ => {
    if (typeof window === 'undefined') return
    let elements = Array.from(ref.querySelectorAll('*'))

    // Scramble text while retaining HTML structure
    // Pass options.excludes as an argument to traverseAndScramble
    elements.forEach(el => traverseAndScramble(el, { excludes }))
  })
</script>

<div {...rest} bind:this={ref} class={klass}>
  {@render children?.()}
</div>
